export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioOutput {
  results: object[];
}

const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_BASE_PREMIUM])),
};
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;
const PROCESSING_FEE = 5;

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / PERCENT;
}

function roundPremiumInMHPCOsFavor(premium: number): number {
  return Math.ceil(premium);
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  return counts;
}

function isBuildingBlock(type: string, count: number): boolean {
  return COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE;
}

function groupBasePremium(type: string, count: number): number {
  return isBuildingBlock(type, count) ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
}

function policyBasePremium(items: Item[]): number {
  let sum = 0;
  for (const [type, count] of countByType(items)) sum += groupBasePremium(type, count);
  return sum;
}

function itemBasePremium(item: Item): number {
  return BASE_PREMIUMS[item.type];
}

function curseSurcharge(item: Item): number {
  return item.cursed ? percentOf(itemBasePremium(item), CURSE_SURCHARGE_PERCENT) : 0;
}

function highEnchantmentSurcharge(item: Item): number {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
    ? percentOf(itemBasePremium(item), HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
    : 0;
}

function itemSurcharges(items: Item[]): number {
  return items.reduce((sum, item) => sum + curseSurcharge(item) + highEnchantmentSurcharge(item), 0);
}

function quotePremium(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const premium =
    basePremium +
    itemSurcharges(items) +
    percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) +
    PROCESSING_FEE;
  return roundPremiumInMHPCOsFavor(premium);
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}
import { describe, expect, it } from "vitest";
import { type Item, runScenario } from "./claimOffice.js";

// Reading: base-premium examples are observed through a newcomer's (0 years) first quote,
// i.e. premium = ceil(base × 1.10 first-insurance + surcharges + 5 G fee).
// Reading: a rejected scenario means the CLI exits non-zero, writes a non-empty
// error description to stderr, and writes nothing to stdout.

function quotePremium(items: Item[], yearsWithMHPCO = 0): number {
  const output = runScenario({ customer: { yearsWithMHPCO }, steps: [{ op: "quote", items }] });
  return (output.results[0] as { premium: number }).premium;
}

function components(type: string, count: number): Item[] {
  return Array.from({ length: count }, () => ({ type }));
}

describe("quote", () => {
  it("empty item list -> premium 5 G (only the processing fee)", () => {
    expect(quotePremium([])).toBe(5);
  });
  it("newcomer plain sword (base 100 G) -> premium 115 G", () => {
    expect(quotePremium([{ type: "sword" }])).toBe(115);
  });
  it("newcomer plain amulet (base 60 G) -> premium 71 G", () => {
    expect(quotePremium([{ type: "amulet" }])).toBe(71);
  });
  it("newcomer plain staff (base 80 G) -> premium 93 G", () => {
    expect(quotePremium([{ type: "staff" }])).toBe(93);
  });
  it("newcomer plain potion (base 40 G) -> premium 49 G", () => {
    expect(quotePremium([{ type: "potion" }])).toBe(49);
  });
  it("newcomer single rune (base 25 G) -> 32.5 G rounded up -> premium 33 G", () => {
    expect(quotePremium([{ type: "rune" }])).toBe(33);
  });
  it("newcomer single moonstone (base 25 G) -> premium 33 G", () => {
    expect(quotePremium([{ type: "moonstone" }])).toBe(33);
  });
  it("2 runes -> base 50 G -> premium 60 G", () => {
    expect(quotePremium(components("rune", 2))).toBe(60);
  });
  it("3 runes -> block base 60 G -> premium 71 G", () => {
    expect(quotePremium(components("rune", 3))).toBe(71);
  });
  it("4 runes -> no block, base 100 G -> premium 115 G", () => {
    expect(quotePremium(components("rune", 4))).toBe(115);
  });
  it("7 runes -> base 175 G -> 197.5 G rounded up in MHPCO's favor -> premium 198 G", () => {
    expect(quotePremium(components("rune", 7))).toBe(198);
  });
  it("2 runes + 1 moonstone -> no block (different types), base 75 G -> premium 88 G", () => {
    expect(quotePremium([...components("rune", 2), ...components("moonstone", 1)])).toBe(88);
  });
  it("3 runes + 3 moonstones -> two blocks, base 120 G -> premium 137 G", () => {
    expect(quotePremium([...components("rune", 3), ...components("moonstone", 3)])).toBe(137);
  });
  it("newcomer cursed steel sword enchantment 3 -> 100 + 50 curse + 10 first = 160 + 5 -> premium 165 G", () => {
    expect(quotePremium([{ type: "sword", material: "steel", enchantment: 3, cursed: true }])).toBe(165);
  });
  it("sword with exactly enchantment 5 -> 100 + 30 + 10 + 5 -> premium 145 G", () => {
    expect(quotePremium([{ type: "sword", enchantment: 5 }])).toBe(145);
  });
  it("cursed sword with exactly enchantment 5 -> both surcharges -> premium 195 G", () => {
    expect(quotePremium([{ type: "sword", enchantment: 5, cursed: true }])).toBe(195);
  });
  it.todo("plain sword with enchantment 4 -> no high-enchantment surcharge -> premium 115 G");
  it.todo("customer with 1 year -> no loyalty discount on sword -> premium 115 G");
  it.todo("customer with exactly 2 years -> loyalty discount on sword -> 100 - 20 + 10 + 5 -> premium 95 G");
  it.todo("cursed sword + plain amulet -> curse on sword only: 160 + 50 + 16 first + 5 -> premium 231 G");
  it.todo("newcomer's second quote of a plain sword -> 100 + 10 - 15 + 5 -> premium 100 G");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 -> premium 160 G (first-insurance still applies)");
});

describe("claim", () => {
  it.todo("regular steel sword enchantment 3, damage 500 G -> payout 400 G, remainingCap 1600 G");
  it.todo("amulet (value 600 G), damage 200 G -> payout 100 G, remainingCap 1100 G");
  it.todo("staff (value 800 G), damage 200 G -> payout 100 G, remainingCap 1500 G");
  it.todo("potion (value 400 G), damage 200 G -> payout 100 G, remainingCap 700 G");
  it.todo("rune (value 250 G), damage 200 G -> payout 100 G, remainingCap 400 G");
  it.todo("moonstone (value 250 G), damage 200 G -> payout 100 G, remainingCap 400 G");
  it.todo("damage below the deductible (sword, 50 G) -> payout 0 G, remainingCap 2000 G (reading: deductible never yields a negative payout)");
  it.todo("steel sword enchantment 9, damage 1000 G -> 50% then deductible -> payout 400 G");
  it.todo("dragon sword exactly enchantment 8, damage 1000 G -> payout 400 G");
  it.todo("dragon sword enchantment 9, damage 1000 G -> 50% rule wins -> payout 400 G");
  it.todo("dragon sword enchantment 5, damage 800 G -> full reimbursement -> payout 700 G");
  it.todo("sword enchantment 8, damage 901 G -> 350.5 G rounded down -> payout 350 G");
  it.todo("sword + amulet damaged 500 G and 300 G -> deductible per item -> payout 600 G, remainingCap 2600 G (cap 3200 G)");
  it.todo("two swords both damaged 500 G -> each own deductible -> payout 800 G, remainingCap 3200 G (cap 4000 G)");
  it.todo("sword + 3 runes (block) -> insurance sum 1750 G; sword damage 500 G -> payout 400 G, remainingCap 3100 G");
  it.todo("cursed sword -> cap 2000 G from unmodified value; damage 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("two successive 1500 G claims on a sword -> 1400/600 then 600/0 (reduced to remaining cap)");
});

describe("claim-office CLI", () => {
  it.todo("schema example (5 years, silver amulet enchantment 2, fire damage 200 G) -> results [{premium 59}, {payout 100, remainingCap 1100}]");
  it.todo("quote with unknown item type broomstick -> non-zero exit, stderr error, no stdout");
  it.todo("claim damaging an amulet when only a sword is insured -> non-zero exit, stderr error, no stdout");
  it.todo("claim damaging an unknown item type -> non-zero exit, stderr error, no stdout");
  it.todo("claim with damage amount -200 -> non-zero exit, stderr error, no stdout");
  it.todo("claim with two sword damages but only one sword insured -> non-zero exit, stderr error, no stdout");
});
# MHPCO Claim Office Kata

## Setting

You are building the policy management system for the **Most Honorable
Privileged Claims Office for Magical Risks and Cursed Items** (MHPCO),
an old-fashioned insurance institution that covers magical items —
swords, amulets, staves, potions, and components such as runes and
moonstones. The MHPCO is bureaucratic, slightly stingy, and proud of
its venerable traditions.

## Feature

The system supports two operations: **quote** computes the premium for
a list of items a customer wishes to insure, and **claim** processes a
damage report against an existing policy.

## Rules

### Item values and base premiums

Each main item has an insurance value and a base premium according to
the MHPCO price list:

- Sword: 1000 G insurance value, 100 G base premium
- Amulet: 600 G / 60 G
- Staff: 800 G / 80 G
- Potion: 400 G / 40 G

Components — for example runes and moonstones — are insured at 250 G
each, with a base premium of 25 G per component. A building block of
3 alike components is offered at a special base premium of 60 G.

### Premium modifiers

- Cursed items add a 50 % risk surcharge.
- Highly enchanted items (enchantment level ≥ 5) add a 30 % risk
  surcharge.
- Long-standing customers (≥ 2 years of business with MHPCO) receive a
  20 % loyalty discount.
- A first insurance carries a 10 % initial assessment surcharge.
- Customers receive a 15 % discount on each contract after their first.
- A 5 G processing fee is added to every premium.

All amounts are rounded to whole G in the MHPCO's favor.

### Claim processing

A deductible of 100 G applies per damage event. The total payout per
policy is capped at twice the insurance sum.

- Damage to items with enchantment level ≥ 8 is reimbursed at 50 % of
  the damage amount.
- Damage to items made of dragon material is fully reimbursed.

## Examples

The examples below illustrate single rules in isolation. Values shown
are base premiums or raw payout amounts before integration with other
modifiers, unless stated otherwise.

### Building block of 3 alike components

- 2 runes → 50 G base premium
- 3 runes → 60 G base premium (block applies)
- 4 runes → 100 G base premium (no block — block requires exactly 3)
- 7 runes → 175 G base premium

### "Alike" components

> ❓ Hmm — "alike" components: does that mean exactly the same type,
> or just the same family (rune-y, gemstone-y)?

- 2 runes + 1 moonstone → 75 G base premium (no block: different types)
- 3 runes + 3 moonstones → 120 G base premium (two separate blocks)

### Modifier scope on multi-item policies

> ❓ A policy with several items: does the cursed surcharge apply to
> the whole policy, or just to the cursed item?

- a policy covers a cursed sword (base premium 100 G) and a plain
  amulet (base premium 60 G) → policy base premium 160 G; the cursed
  surcharge adds 50 G (50 % of the cursed sword's base premium, not
  of the policy total) → 210 G before further modifiers and fee
- item-specific modifiers (cursed, high enchantment) apply to the
  base premium of the affected item; policy-wide modifiers (loyalty,
  first insurance, follow-up contract) apply to the policy base
  premium (the sum of all item base premiums); the processing fee is
  added at the very end

### Modifier thresholds

- customer with exactly 2 years with MHPCO → loyalty discount applies
- sword with exactly enchantment 5 → high-enchantment surcharge
  applies; if cursed, both surcharges apply
- sword with enchantment 4 → no high-enchantment surcharge; curse
  surcharge applies only if cursed
- dragon-material sword with exactly enchantment 8, damage 1000 G →
  payout 400 G (high-enchantment clause applies, then deductible)

### Deductible per damage event

- a dragon attack damages an insured sword (500 G) and an insured
  amulet (300 G); payout = 600 G (the 100 G deductible applies once
  per damaged item)

### Standard reimbursement (no special clauses)

- regular sword (steel, enchantment 3), damage 500 G → payout 400 G
  (full reimbursement minus 100 G deductible; no special clause applies)
- damage to a rune (insurance value 250 G), damage 200 G → payout
  100 G (full reimbursement minus 100 G deductible; runes have no
  enchantment level or material, so no special clause applies)

### Enchantment threshold vs. dragon material

- dragon-material sword, enchantment 9, damage 1000 G → payout 400 G
  (both clauses apply; the 50 % rule wins, then deductible: 500 − 100)
- dragon-material sword, enchantment 5, damage 800 G → payout 700 G

